const body = $input.first().json.body || {};
if (!body.topic || !body.executionId) throw new Error('Missing required fields: topic and executionId');
const topic = String(body.topic).trim();
const executionId = body.executionId;
const options = body.options || {};
const maxPapers = Math.min(20, Math.max(1, Number(options.maxPapers || 10)));
return [{ json: { topic, executionId, options, maxPapers, startedAt: new Date().toISOString() } }];

const chainOutput = $input.first().json;
const initData = $('Initialise State').first().json;
const text = chainOutput.text || chainOutput.output || '';
let queries = [];
try {
  const cleaned = text.replace(/```json|```/g, '').trim();
  queries = JSON.parse(cleaned);
  if (!Array.isArray(queries)) throw new Error('Not array');
  queries = queries.filter(q => typeof q === 'string' && q.length > 0).slice(0, 4);
} catch (e) {
  queries = [initData.topic, initData.topic + ' review', initData.topic + ' systematic review', initData.topic + ' applications'];
}
return [{ json: { ...initData, queries } }];

const items = $input.all();
const allPapers = [];

const restoreAbstract = (inv) => {
  if (!inv || typeof inv !== 'object') return '';
  const words = [];
  for (const [w, pos] of Object.entries(inv)) { for (const p of pos || []) words[p] = w; }
  return words.filter(Boolean).join(' ');
};

const normDoi = (doi) => {
  if (!doi) return '';
  const v = String(doi).trim();
  return v.startsWith('http') ? v : 'https://doi.org/' + v.replace(/^doi:/i, '');
};

for (const item of items) {
  let data = item.json;
  if (typeof data === 'string') { try { data = JSON.parse(data); } catch (e) {} }

  // OpenAlex
  if (data && Array.isArray(data.results)) {
    for (const p of data.results) {
      const title = p.title || p.display_name || '';
      const abstract = restoreAbstract(p.abstract_inverted_index);
      if (!title.trim() || !abstract.trim()) continue;
      const doiUrl = normDoi(p.doi);
      const landingUrl = p.primary_location?.landing_page_url || p.id || '';
      allPapers.push({
        source: 'openalex',
        externalId: p.id || p.doi || '',
        title: title.trim(), abstract: abstract.trim(),
        authors: (p.authorships || []).map(a => a.author?.display_name).filter(Boolean).join(', '),
        year: p.publication_year || 0,
        citationCount: p.cited_by_count || 0,
        venue: p.primary_location?.source?.display_name || '',
        url: doiUrl || landingUrl || p.id || '',
        pdfUrl: p.primary_location?.pdf_url || p.open_access?.oa_url || '',
        isOpenAccess: Boolean(p.open_access?.is_oa)
      });
    }
  }

  // Semantic Scholar
  if (data && Array.isArray(data.data)) {
    for (const p of data.data) {
      if (!p.title || !p.abstract) continue;
      const doiUrl = normDoi(p.externalIds?.DOI);
      allPapers.push({
        source: 'semantic_scholar',
        externalId: p.paperId || '',
        title: String(p.title).trim(),
        abstract: String(p.abstract).trim(),
        authors: (p.authors || []).map(a => a.name).join(', '),
        year: p.year || 0,
        citationCount: p.citationCount || 0,
        venue: p.venue || '',
        url: doiUrl || p.url || '',
        pdfUrl: p.openAccessPdf?.url || '',
        isOpenAccess: Boolean(p.openAccessPdf?.url)
      });
    }
  }
}

const seen = new Set();
const deduped = [];
for (const p of allPapers) {
  const key = p.title.toLowerCase().replace(/[^a-z0-9]/g, '').substring(0, 60);
  if (!seen.has(key)) { seen.add(key); deduped.push(p); }
}

return deduped.map(p => ({ json: p }));

const httpResults = $input.all();
const valid = [];
const MIN_YEAR = 2000;

for (let i = 0; i < httpResults.length; i++) {
  const httpItem = httpResults[i].json;
  // Recover the original paper from the Normalise node using paired item index
  const paper = $('Normalise + Deduplicate').itemMatching(i).json;

  // Link validation: reject 4xx/5xx responses; allow failures on short-lived links
  const status = httpItem.statusCode;
  if (status && status >= 400) continue;

  // Rule-based quality checks
  if (!paper.abstract || paper.abstract.length < 30) continue;
  if (paper.year && paper.year < MIN_YEAR) continue;
  if (!paper.title || paper.title.length < 10) continue;

  valid.push({ json: paper });
}

return valid;

const chainOutput = $input.first().json;
const text = chainOutput.text || chainOutput.output || '';
// Recover the original paper using paired item; the chain outputs one item per input
const paper = $('Filter: Link Check + Rules').itemMatching($itemIndex).json;

let scoring = { quality_score: 5, relevance_score: 5, credibility_score: 5, keep: true, primary_theme: 'general', reason: 'Default scoring' };
try {
  const cleaned = text.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(cleaned);
  scoring = {
    quality_score:     Math.min(10, Math.max(0, parseFloat(parsed.quality_score)     || 5)),
    relevance_score:   Math.min(10, Math.max(0, parseFloat(parsed.relevance_score)   || 5)),
    credibility_score: Math.min(10, Math.max(0, parseFloat(parsed.credibility_score) || 5)),
    keep:              Boolean(parsed.keep !== false),
    primary_theme:     (parsed.primary_theme || 'general').substring(0, 60),
    reason:            (parsed.reason || '').substring(0, 200)
  };
} catch (e) {}

return [{ json: { ...paper, scoring } }];

const data = $('Initialise State').first().json;
const maxPapers = Math.min(20, Math.max(1, Number(data.maxPapers || 10)));

const sorted = $input.all()
  .map(i => i.json)
  .sort((a, b) => {
    const score = p => (p.scoring?.quality_score || 0) + (p.scoring?.relevance_score || 0) + (p.scoring?.credibility_score || 0) + Math.log10((p.citationCount || 0) + 1);
    return score(b) - score(a);
  })
  .slice(0, maxPapers);

const themeMap = {};
for (const p of sorted) {
  const t = p.scoring?.primary_theme || 'research literature';
  if (!themeMap[t]) themeMap[t] = [];
  themeMap[t].push(p.title);
}
const themes = Object.keys(themeMap).slice(0, 6);

return [{ json: { executionId: data.executionId, topic: data.topic, validatedPapers: sorted, themes, paperCount: sorted.length } }];

const data = $input.first().json;
const papers = data.validatedPapers || [];
const topic = data.topic;
const themes = data.themes || [];

const paperList = papers.slice(0, 12).map((p, i) =>
  '[' + (i + 1) + '] "' + p.title + '" (' + (p.year || 'n.d.') + ', ' + (p.citationCount || 0) + ' citations)\nAuthors: ' + (p.authors || 'Unknown') + '\nVenue: ' + (p.venue || 'Unknown') + '\nAbstract: ' + ((p.abstract || '').substring(0, 400)) + '...'
).join('\n\n');

return [{ json: { ...data, paperList, themes } }];

const chainOutput = $input.first().json;
const data = $('Build Synthesis Prompt').first().json;
const text = chainOutput.text || chainOutput.output || '';

let surveyContent = null;
try {
  const cleaned = text.replace(/^```json\s*/, '').replace(/```\s*$/, '').trim();
  surveyContent = JSON.parse(cleaned);
} catch (e) {
  surveyContent = { introduction: 'Parsing error — please retry.', themes: [], methodologies: '', keyFindings: '', limitations: '', researchGaps: '', conclusion: '' };
}

const references = (data.validatedPapers || []).map(p => ({
  authors: typeof p.authors === 'string' ? p.authors.split(',').map(s => s.trim()).filter(Boolean) : (Array.isArray(p.authors) ? p.authors : []),
  year:    Number(p.year) || new Date().getFullYear(),
  title:   p.title || 'Untitled',
  venue:   p.venue || '',
  url:     p.url || p.pdfUrl || undefined
}));

const extraSection = (title, content) => content && String(content).trim()
  ? [{ title, content: String(content), paperIds: [] }] : [];

const sections = [
  ...(surveyContent.themes || []).map(t => ({ title: String(t.title || 'Theme'), content: String(t.content || ''), paperIds: (t.paperRefs || []).map(String) })),
  ...extraSection('Methodologies',  surveyContent.methodologies),
  ...extraSection('Key Findings',   surveyContent.keyFindings),
  ...extraSection('Limitations',    surveyContent.limitations),
  ...extraSection('Research Gaps',  surveyContent.researchGaps)
];

const countWords = s => (String(s || '').match(/\S+/g) || []).length;
const wordCount = countWords(surveyContent.introduction) + countWords(surveyContent.conclusion) +
  sections.reduce((sum, s) => sum + countWords(s.content), 0);

const survey = {
  content: {
    introduction: String(surveyContent.introduction || ''),
    sections,
    conclusion:   String(surveyContent.conclusion || ''),
    references
  },
  metadata: {
    paperCount:  data.validatedPapers ? data.validatedPapers.length : 0,
    wordCount,
    generatedAt: new Date().toISOString(),
    themes:      data.themes || []
  }
};

return [{ json: { executionId: data.executionId, topic: data.topic, survey } }];
